use fastflyer::{Flyer,Kind,Coord};use fastflyer::debug::TickTrace;use std::{collections::{BTreeMap,BTreeSet},io::Write};
fn snapshot(f:&Flyer,ids:&BTreeMap<Coord,usize>,parity:usize)->BTreeMap<usize,[i64;5]>{let bs=f.blocks();let a=bs.iter().filter(|(_,b)|b.kind()==Kind::Slime).map(|(p,_)|p.x).min().unwrap()-3;let b=bs.iter().filter(|(_,b)|b.kind()==Kind::Honey).map(|(p,_)|p.x).min().unwrap()-3;let mut owner=BTreeMap::new();for(p,bb)in &bs{if bb.kind()==Kind::Piston{for q in f.piston_blocks(*p){owner.insert(*q,if p.z==6{0}else{1});}}}let mut out=BTreeMap::new();for(p,bb)in bs{if bb.kind()==Kind::Piston{let bank=if p.z==6{0}else{1};let m=if bb.moving(){*owner.get(&p).expect("moving piston owner")}else{-1};out.insert(ids[&p],[parity as i64,bank,p.x-5-if bank==0{a}else{b},bb.state() as i64,m]);}}out}
fn main(){let args:Vec<_>=std::env::args().collect();let mut rows=BTreeSet::new();for seed in 0..8{for phase in [0,7,8,15]{let mut f=Flyer::load(&args[1]).unwrap();f.rng_state=seed;f.phase_x=phase;let mut ids:BTreeMap<_,_>=f.blocks().into_iter().filter(|(_,b)|b.kind()==Kind::Piston).enumerate().map(|(i,(p,_))|(p,i)).collect();for t in 0..500{let old=snapshot(&f,&ids,t%2);let mut tr=TickTrace::new(&f);let r=f.tick_traced(&mut tr,t).unwrap();assert_eq!(r.extensions_started,1);for s in &tr.steps{if let Some(m)=&s.info.movement{if m.failure.is_none(){let moving:Vec<_>=m.sources.iter().filter_map(|p|ids.remove(p).map(|i|(*p,i))).collect();for(p,i)in moving{assert!(ids.insert(Coord::new(p.x+1,p.y,p.z),i).is_none());}}}}let new=snapshot(&f,&ids,1-t%2);for (i,q)in old{rows.insert((q,new[&i]));}}}}let mut out=std::fs::File::create(&args[2]).unwrap();for(q,r)in &rows{writeln!(out,"{},{},{},{},{},{},{},{},{},{}",q[0],q[1],q[2],q[3],q[4],r[0],r[1],r[2],r[3],r[4]).unwrap();}println!("{} unique observed transitions, 32 x 500 full-sim ticks",rows.len());}
